-- Java LSP configuration using nvim-jdtls + bemol (for Brazil workspaces)

local jdtls = require 'jdtls'

-- Prefer the .bemol root (generated by bemol in Brazil workspaces), else a regular build root
local root_dir = vim.fs.root(0, '.bemol') or vim.fs.root(0, { 'gradlew', 'mvnw', 'settings.gradle', 'settings.gradle.kts', 'pom.xml', 'build.gradle', '.git' })
if not root_dir then return end

local project_name = vim.fn.fnamemodify(root_dir, ':p:h:t')
local workspace_dir = vim.fn.stdpath 'cache' .. '/jdtls/workspace/' .. project_name

-- Mason paths
local path_to_mason = vim.fn.stdpath 'data' .. '/mason'
local path_to_jdtls = path_to_mason .. '/packages/jdtls'
local path_to_lombok = path_to_mason .. '/share/jdtls/lombok.jar'
local path_to_plugins = path_to_jdtls .. '/plugins/'

-- jdtls ships one config dir per platform: config_{linux,mac,win}[_arm]
local uname = vim.uv.os_uname()
local os_name = ({ Darwin = 'mac', Linux = 'linux', Windows_NT = 'win' })[uname.sysname] or 'linux'
local arch = (uname.machine == 'arm64' or uname.machine == 'aarch64') and '_arm' or ''
local path_to_config = path_to_jdtls .. '/config_' .. os_name .. arch

-- Find the equinox launcher jar (version-suffixed)
local path_to_jar = vim.fs.find(function(name, _) return name:match 'org.eclipse.equinox.launcher_.*' end, { path = path_to_plugins, type = 'file' })[1]

if not path_to_jar then
  vim.notify('jdtls: Could not find equinox launcher jar. Run :Mason and install jdtls.', vim.log.levels.ERROR)
  return
end

-- Use Java 25 to run jdtls (LTS, required since jdtls 1.63), falling back to whatever java is on PATH
local java_cmd = vim.fn.exepath 'java'
if vim.fn.executable '/usr/libexec/java_home' == 1 then
  local result = vim.system({ '/usr/libexec/java_home', '-v', '25' }):wait()
  if result.code == 0 then java_cmd = vim.trim(result.stdout) .. '/bin/java' end
end

-- Bemol integration: add workspace folders generated by bemol
local function bemol()
  local bemol_dir = vim.fs.find({ '.bemol' }, { upward = true, type = 'directory' })[1]
  if not bemol_dir then return end

  local file = io.open(bemol_dir .. '/ws_root_folders', 'r')
  if not file then return end

  local ws_folders = {}
  for line in file:lines() do
    table.insert(ws_folders, line)
  end
  file:close()

  local current_folders = vim.lsp.buf.list_workspace_folders()
  for _, folder in ipairs(ws_folders) do
    if not vim.tbl_contains(current_folders, folder) then vim.lsp.buf.add_workspace_folder(folder) end
  end
end

local config = {
  cmd = {
    java_cmd,
    '-Declipse.application=org.eclipse.jdt.ls.core.id1',
    '-Dosgi.bundles.defaultStartLevel=4',
    '-Declipse.product=org.eclipse.jdt.ls.core.product',
    '-Dlog.protocol=true',
    '-Dlog.level=ALL',
    '-Xmx2g',
    '-javaagent:' .. path_to_lombok,
    '--add-modules=ALL-SYSTEM',
    '--add-opens',
    'java.base/java.util=ALL-UNNAMED',
    '--add-opens',
    'java.base/java.lang=ALL-UNNAMED',
    '-jar',
    path_to_jar,
    '-configuration',
    path_to_config,
    '-data',
    workspace_dir,
  },

  root_dir = root_dir,

  -- jdtls.start_or_attach bypasses vim.lsp.config, so pass blink.cmp's capabilities explicitly
  capabilities = require('blink.cmp').get_lsp_capabilities(),

  settings = {
    java = {
      references = {
        includeDecompiledSources = true,
      },
      eclipse = {
        downloadSources = true,
      },
      maven = {
        downloadSources = true,
      },
      sources = {
        organizeImports = {
          starThreshold = 9999,
          staticStarThreshold = 9999,
        },
      },
    },
  },

  on_attach = bemol,
}

jdtls.start_or_attach(config)
